// VersionLTE applies the LTE predicate on the "version" field.
func VersionLTE(v int64) predicate.ContestScoringAttempt {
	return predicate.ContestScoringAttempt(sql.FieldLTE(FieldVersion, v))
}

// HasContest applies the HasEdge predicate on the "contest" edge.
func HasContest() predicate.ContestScoringAttempt {
	return predicate.ContestScoringAttempt(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ContestTable, ContestColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasContestWith applies the HasEdge predicate on the "contest" edge with a given conditions (other predicates).
func HasContestWith(preds ...predicate.Contest) predicate.ContestScoringAttempt {
	return predicate.ContestScoringAttempt(func(s *sql.Selector) {
		step := newContestStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

