// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ContestScoringAttempt) predicate.ContestScoringAttempt {
	return predicate.ContestScoringAttempt(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ContestScoringAttempt) predicate.ContestScoringAttempt {
	return predicate.ContestScoringAttempt(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ContestScoringAttempt) predicate.ContestScoringAttempt {
	return predicate.ContestScoringAttempt(sql.NotPredicates(p))
}
